/* =====================================================================
   AUDIO (BGM / SE)
   すべてWeb Audio APIで合成する(外部音源ファイルなし・ビルドレス維持)。
   - 初回のユーザー操作でAudioContextを起動(iOS Safariの自動再生制限対応)
   - BGM: タイトル(のどかな牧場) / 試合中(残り人数で段階変化) / 残り5人以下(壮大)
   - SE: 負荷対策として自分の操作モンスターに関わる音のみ鳴らす
===================================================================== */

// ===== 音量設定(localStorage永続化) =====
const AUDIO_SETTINGS_KEY = 'aramon_audio_v1';
let audioSettings = { bgm: 0.5, se: 0.7 };
try {
  const saved = JSON.parse(localStorage.getItem(AUDIO_SETTINGS_KEY));
  if(saved && typeof saved.bgm==='number' && typeof saved.se==='number'){
    audioSettings = { bgm: Math.min(1,Math.max(0,saved.bgm)), se: Math.min(1,Math.max(0,saved.se)) };
  }
} catch(e){}
function saveAudioSettings(){
  try { localStorage.setItem(AUDIO_SETTINGS_KEY, JSON.stringify(audioSettings)); } catch(e){}
}

let actx = null, seGain = null, bgmGain = null, bgmTrackGain = null;
function applyAudioVolumes(){
  if(seGain) seGain.gain.value = audioSettings.se;
  if(bgmGain) bgmGain.gain.value = audioSettings.bgm;
}
function audioInit(){
  if(actx) return;
  const AC = window.AudioContext || window.webkitAudioContext;
  if(!AC) return;
  actx = new AC();
  seGain = actx.createGain(); seGain.connect(actx.destination);
  bgmGain = actx.createGain(); bgmGain.connect(actx.destination);
  bgmTrackGain = actx.createGain(); bgmTrackGain.gain.value = 1; bgmTrackGain.connect(bgmGain);
  applyAudioVolumes();
  startBgmScheduler();
  ensureSsrJackpotBuffer();
  ensureZeusTier3Buffer();
  ensureBestUpdateBuffer();
  ensureBgmFileBuffers();
  ensureChocoSeBuffers();
  ensureTitleStartSeBuffer();
  ensureSsrPromoteSeBuffer();
  // ピックアップは出る確率が高いので先読みする(スキンガチャ・レイドガチャの両方)
  ensureSkinPromoteSe(typeof GACHA_PICKUP_SSR!=='undefined' ? GACHA_PICKUP_SSR : null);
  ensureSkinPromoteSe(typeof RAID_GACHA_PICKUP!=='undefined' ? RAID_GACHA_PICKUP : null);
  ensureProvidedSeBuffers();
  ensureBgmLobbyBuffer();
}
// 初回のタップ/クリック/キーで起動+復帰(iOSはユーザー操作が無いと音が出せない)
['pointerdown','touchend','keydown'].forEach(ev=>{
  window.addEventListener(ev, ()=>{
    audioInit();
    if(actx && actx.state==='suspended') actx.resume();
  }, {capture:true, passive:true});
});
// バックグラウンドでは停止(電池・音の積み残し対策)
document.addEventListener('visibilitychange', ()=>{
  if(!actx) return;
  if(document.hidden) actx.suspend();
  else actx.resume();
});

// ===== SSR獲得SE(実録音の埋め込み再生) =====
// 発注者提供の音声(パチンコ大当たり確定音)をmp3データURIで内蔵し、Web Audioで再生する。
// 外部ファイル参照はせず自己完結(SWキャッシュ対象・オフライン可)。演出中はループ再生。
const SSR_JACKPOT_DATAURL = 'data:audio/mpeg;base64,';
// ===== ゼウス(SSR)tier3専用SE(実録音の埋め込み再生) =====
const ZEUS_TIER3_DATAURL = 'data:audio/mpeg;base64,';
let ssrJackpotBuffer = null, ssrJackpotSource = null, ssrJackpotLoopWanted = false, ssrJackpotDecoding = false;
function ensureSsrJackpotBuffer(){
  if(ssrJackpotBuffer || ssrJackpotDecoding || !actx) return;
  ssrJackpotDecoding = true;
  fetch(SSR_JACKPOT_DATAURL).then(r=>r.arrayBuffer()).then(a=>actx.decodeAudioData(a))
    .then(buf=>{ ssrJackpotBuffer = buf; ssrJackpotDecoding=false; if(ssrJackpotLoopWanted) startSsrJackpotLoop(); })
    .catch(()=>{ ssrJackpotDecoding=false; });
}
function playSsrJackpotOnce(){
  if(!actx || audioSettings.se<=0.005){ ensureSsrJackpotBuffer(); return; }
  if(!ssrJackpotBuffer){ ensureSsrJackpotBuffer(); return; }
  const src = actx.createBufferSource(); src.buffer = ssrJackpotBuffer;
  const g = actx.createGain(); g.gain.value = 1.3;
  src.connect(g); g.connect(seGain); src.start();
}
function startSsrJackpotLoop(){
  ssrJackpotLoopWanted = true;
  if(!actx || audioSettings.se<=0.005){ ensureSsrJackpotBuffer(); return; }
  if(!ssrJackpotBuffer){ ensureSsrJackpotBuffer(); return; }
  stopSsrJackpotSource();
  const src = actx.createBufferSource(); src.buffer = ssrJackpotBuffer; src.loop = true;
  const g = actx.createGain(); g.gain.value = 1.3;
  src.connect(g); g.connect(seGain); src.start();
  ssrJackpotSource = src;
}
function stopSsrJackpotSource(){ if(ssrJackpotSource){ try{ ssrJackpotSource.stop(); }catch(e){} ssrJackpotSource=null; } }
function stopSsrJackpotLoop(){ ssrJackpotLoopWanted = false; stopSsrJackpotSource(); }

// リザルトの自己ベスト更新SE。発注者提供動画の音声(約9秒)を外部mp3として読み込み、
// ループせず一回だけ再生する。未ロード/取得失敗時はSSR獲得SEにフォールバック(無音回避)。
let bestUpdateBuffer = null, bestUpdateDecoding = false, bestUpdateSource = null;
const BEST_UPDATE_URL = './audio/best_update.mp3';
function ensureBestUpdateBuffer(){
  if(bestUpdateBuffer || bestUpdateDecoding || !actx) return;
  bestUpdateDecoding = true;
  fetch(BEST_UPDATE_URL).then(r=>r.arrayBuffer()).then(a=>actx.decodeAudioData(a))
    .then(buf=>{ bestUpdateBuffer = buf; bestUpdateDecoding=false; })
    .catch(()=>{ bestUpdateDecoding=false; });
}
function playBestUpdateOnce(){
  if(!actx || audioSettings.se<=0.005){ ensureBestUpdateBuffer(); return; }
  if(!bestUpdateBuffer){ ensureBestUpdateBuffer(); if(typeof playSsrJackpotOnce==='function') playSsrJackpotOnce(); return; } // 未ロード時は従来SEで代替
  if(bestUpdateSource){ try{ bestUpdateSource.stop(); }catch(e){} bestUpdateSource=null; } // 二重再生防止(ループしない)
  const src = actx.createBufferSource(); src.buffer = bestUpdateBuffer;
  const g = actx.createGain(); g.gain.value = 1.2;
  src.connect(g); g.connect(seGain); src.start();
  bestUpdateSource = src;
  src.onended = ()=>{ if(bestUpdateSource===src) bestUpdateSource=null; };
}

// ゼウス(SSR)装備時のtier3「ゴッドライジング」専用SE。発注者提供動画の音声を内蔵mp3データURIで再生。
// 未ロード/取得失敗時は通常のgodRising合成SEにフォールバック(playSeの分岐で対応)。
let zeusTier3Buffer = null, zeusTier3Decoding = false;
function ensureZeusTier3Buffer(){
  if(zeusTier3Buffer || zeusTier3Decoding || !actx) return;
  zeusTier3Decoding = true;
  fetch(ZEUS_TIER3_DATAURL).then(r=>r.arrayBuffer()).then(a=>actx.decodeAudioData(a))
    .then(buf=>{ zeusTier3Buffer = buf; zeusTier3Decoding=false; })
    .catch(()=>{ zeusTier3Decoding=false; });
}
// 再生できたらtrue、まだ準備できていなければfalse(呼び出し側で合成SEにフォールバック)
function playZeusTier3Once(){
  if(!actx || audioSettings.se<=0.005){ ensureZeusTier3Buffer(); return false; }
  if(!zeusTier3Buffer){ ensureZeusTier3Buffer(); return false; }
  const src = actx.createBufferSource(); src.buffer = zeusTier3Buffer;
  const g = actx.createGain(); g.gain.value = 1.3;
  src.connect(g); g.connect(seGain); src.start();
  return true;
}

// ちょこ(ピクシーSSR)の召喚演出SE(発注者提供動画の音声)
const CHOCO_SUMMON_DATAURL = 'data:audio/mpeg;base64,';
// ちょこ(ピクシーSSR)のtier3「ヴァニッシュ」SE(発注者提供動画の音声)
const CHOCO_VANISH_DATAURL = 'data:audio/mpeg;base64,';
// ちょこ(ピクシーSSR)の被弾SE(発注者提供動画の音声。冒頭0.5秒の無音と末尾の無音は切り落とし済み)
const CHOCO_HIT_DATAURL = 'data:audio/mpeg;base64,';

// タイトル画面「TAP START」タップ時のSE(発注者提供音源)
const TITLE_START_DATAURL = 'data:audio/mpeg;base64,';

// SSR昇格演出の音声(発注者提供動画から抽出。動画は音無しで別途配置し、再生開始と同時にこちらを鳴らす)
const SSR_PROMOTE_SE_DATAURL = 'data:audio/mpeg;base64,';

// 内蔵mp3データURIの短いSEを1回だけ鳴らす小さなラッパ(ちょこの3種で共用)。
// playZeusTier3Onceと同じ方式だが、音源が増えても同じコードを増やさないようにまとめている。
// 未ロード/音量0のときはfalseを返すので、呼び出し側は合成SEにフォールバックできる。
function createSeOneShot(dataUrl, gainVal){
  const S = { buffer:null, decoding:false };
  S.ensure = ()=>{
    if(S.buffer || S.decoding || !actx) return;
    S.decoding = true;
    S._loading = fetch(dataUrl).then(r=>r.arrayBuffer()).then(a=>actx.decodeAudioData(a))
      .then(buf=>{ S.buffer = buf; S.decoding = false; })
      .catch(()=>{ S.decoding = false; });
  };
  /* 読み込みが終わるまで待つ(最大 timeoutMs)。読めたら true。
     昇格演出のように「動画と音声を必ず同時に鳴らしたい」場面で、
     先読みが間に合っていなくても無音にしないために使う。 */
  S.ready = (timeoutMs)=>{
    if(S.buffer) return Promise.resolve(true);
    if(!actx) return Promise.resolve(false);
    S.ensure();
    const waitLoad = (S._loading || Promise.resolve()).then(()=>!!S.buffer);
    const timeout = new Promise(res=>setTimeout(()=>res(!!S.buffer), timeoutMs||6000));
    return Promise.race([waitLoad, timeout]);
  };
  // when を渡すとその時刻から鳴らす(音源のあとに合成SEをつなげたいときに使う)
  S.play = (when)=>{
    if(!actx || audioSettings.se<=0.005){ S.ensure(); return false; }
    if(!S.buffer){ S.ensure(); return false; }
    const src = actx.createBufferSource(); src.buffer = S.buffer;
    const g = actx.createGain(); g.gain.value = (gainVal!=null ? gainVal : 1.2);
    src.connect(g); g.connect(seGain); src.start(when!=null ? when : actx.currentTime);
    return true;
  };
  S.dur = ()=> S.buffer ? S.buffer.duration : 0;
  return S;
}
// ちょこ(ピクシーSSR)専用SE: 召喚演出 / tier3「ヴァニッシュ」 / 被弾
const seChocoSummon = createSeOneShot(CHOCO_SUMMON_DATAURL, 1.25);
const seChocoVanish = createSeOneShot(CHOCO_VANISH_DATAURL, 1.3);
const seChocoHit    = createSeOneShot(CHOCO_HIT_DATAURL, 1.15);
function ensureChocoSeBuffers(){ seChocoSummon.ensure(); seChocoVanish.ensure(); seChocoHit.ensure(); }
// タイトル画面のスタートSE
const seTitleStart = createSeOneShot(TITLE_START_DATAURL, 1.2);
function ensureTitleStartSeBuffer(){ seTitleStart.ensure(); }
// SSR昇格演出の音声(動画は音無し。動画再生開始と同時にこちらを鳴らす)
const seSsrPromote = createSeOneShot(SSR_PROMOTE_SE_DATAURL, 1.2);
function ensureSsrPromoteSeBuffer(){ seSsrPromote.ensure(); }
// 発注者提供の実音源SE。1.2秒以下は内蔵データURI、3秒級は外部mp3(どちらもfetchで同じ扱い)
const SE_CHOICE_DATAURL  = 'data:audio/mpeg;base64,';
const SE_BUY_DATAURL     = 'data:audio/mpeg;base64,';
const SE_MONTA_DATAURL   = 'data:audio/mpeg;base64,';
const SE_REQUIEM_DATAURL = 'data:audio/mpeg;base64,';
const SE_BARD_DATAURL    = 'data:audio/mpeg;base64,';
const seChoice      = createSeOneShot(SE_CHOICE_DATAURL, 0.95);  // 共通のボタンタップ
const seBuy         = createSeOneShot(SE_BUY_DATAURL, 1.15);     // ショップ購入
const seMonta       = createSeOneShot(SE_MONTA_DATAURL, 1.25);   // モッチー tier1「もんた」
const seRequiemEnd  = createSeOneShot(SE_REQUIEM_DATAURL, 1.25); // イルミネ tier3「レクイエムエンド」
const seBard        = createSeOneShot(SE_BARD_DATAURL, 1.25);    // ヒノトリ tier3の前半(このあと炎をつなげる)
const seDarkHoust   = createSeOneShot('./audio/se_darkhost.mp3', 1.25);   // ザン tier3「ダークホウスト」
const seMocchiBeam  = createSeOneShot('./audio/se_mocchibeam.mp3', 1.25); // モッチー tier3「モッチ砲/ラガモッチ砲」
const seCrystalRain = createSeOneShot('./audio/se_crystal.mp3', 1.25);    // ウンディーネ tier3「クリスタルレイン」
const SE_AMPHI_SHOT_DATAURL = 'data:audio/mpeg;base64,';
const seAmphiShot     = createSeOneShot(SE_AMPHI_SHOT_DATAURL, 1.2);       // ペルセポネ tier3「アムピトリテ」の発射(3連射で使う)
const seAmphiBlast    = createSeOneShot('./audio/se_amphitrite_blast.mp3', 1.2); // 同・着弾ドームの爆発(ドーム1個ごとに鳴る)
const SE_VENOM_DATAURL = 'data:audio/mpeg;base64,';
// 轟金剛(ゴーレムのSSR): tier3「超番長ボーナス」・勝利・キルの専用音
const seGokongo       = createSeOneShot('./audio/se_gokongo.mp3', 1.25);
/* SSRスキンの昇格演出の音声(動画は音無しで、こちらを同時に鳴らす)。
   どのスキンにどの音源を使うかは data.js の SKIN_MEDIA が持っているので、
   ここでは表を1周してワンショットを作るだけにする(スキンを足してもこの行は増えない)。 */
const skinPromoteSeOneShots = {};
Object.keys(typeof SKIN_MEDIA!=='undefined' ? SKIN_MEDIA : {}).forEach(id=>{
  const p = SKIN_MEDIA[id].promote;
  if(p && p.audio) skinPromoteSeOneShots[id] = createSeOneShot('./' + p.audio, 1.0);
});
function skinPromoteSe(skinId){ return skinPromoteSeOneShots[skinId] || null; }
function ensureSkinPromoteSe(skinId){
  const s = skinPromoteSeOneShots[skinId];
  if(s) s.ensure();
}
// 転生演出専用の音声(約8.5秒)。演出のCSSアニメーションと尺を合わせてあるので、
// 長さを変えるときは ui.js の REBIRTH_ANIM_MS と各キーフレームも一緒に直すこと。
const seRebirth = createSeOneShot('./audio/rebirth_audio.mp3', 1.0);
function ensureRebirthSeBuffer(){ seRebirth.ensure(); }
function playRebirthSe(){ return seRebirth.play(); }
const seGokongoWin    = createSeOneShot('./audio/se_gokongo_win.mp3', 1.2);
const seGokongoKill   = createSeOneShot('./audio/se_gokongo_kill.mp3', 1.2);
// 大喰いの利世(ウンディーネのSSR): tier3「鱗赫」・キル・被弾の専用音
const seRize          = createSeOneShot('./audio/se_rize.mp3', 1.25);
const seRizeKill      = createSeOneShot('./audio/se_rize_kill.mp3', 1.2); // 現在は勝利SEに転用(SKIN_WIN_SE参照)
const seRizeHit       = createSeOneShot('./audio/se_rize_hit.mp3', 1.15);
const seAquaKill      = createSeOneShot('./audio/se_aqua_kill.mp3', 1.2); // 新しいキルSE(SKIN_KILL_SE参照)
const seGutsTier3     = createSeOneShot('./audio/se_guts_tier3.mp3', 1.2); // 狂戦士ガッツ tier3「ドラゴンころし」の発動音
const seVenomEdge     = createSeOneShot(SE_VENOM_DATAURL, 1.25);            // イルミネ tier1「ヴェノムエッジ」(tier2は同じ音の3連射)
const seRequiemBlast  = createSeOneShot('./audio/se_requiem_blast.mp3', 1.2);     // イルミネ tier3「レクイエムエンド」の着弾ドーム
function ensureProvidedSeBuffers(){
  [seChoice, seBuy, seMonta, seRequiemEnd, seBard, seDarkHoust, seMocchiBeam, seCrystalRain,
   seAmphiShot, seAmphiBlast, seVenomEdge, seRequiemBlast,
   seGokongo, seGokongoWin, seGokongoKill,
   seRize, seRizeKill, seRizeHit, seAquaKill, seGutsTier3].forEach(s=>s.ensure());
}

// ===== SE =====
// 同じSEの最低再生間隔(秒)。連打・毎フレーム呼び出しでの音割れ防止
const SE_MIN_GAP = { tap:0.05, cardSwipe:0.07, jakiin:0.25, train:0.3, pickup:0.1, fire:0.06, hitTaken:0.12, noGuts:0.5, kill:0.15, fanfare:1.5, sad:1.5,
  fireRoar:0.3, iceCrack:0.3, tornado:0.3, spin:0.25, beam:0.3, whoosh:0.2, bell:0.3, chupiin:1, shuwaa:1.5, godRising:0.8, zashu:0.6, ssrJackpot:0.9, zeusTier3:0.8,
  chocoSummon:1.5, chocoVanish:0.8, chocoHit:0.5, titleStart:1.2,
  buy:0.2, darkHoust:0.6, requiemEnd:0.3, mocchiBeam:0.5, monta:0.2, crystalRain:0.5, fireWave:0.5,
  amphitrite:0.8, amphitriteBlast:0.06, venomEdge:0.2, assaultArrow:0.5, requiemBlast:0.06,
  gokongo:0.8, gokongoWin:1.5, gokongoKill:0.4,
  rize:0.8, rizeKill:0.4, rizeHit:0.3 };
const seLastAt = {};
// 技SEは他のSEより一回り大きく鳴らす(名前ごとの音量倍率)
const SE_VOL_BOOST = { fire:1.35, fireRoar:1.35, iceCrack:1.35, tornado:1.35, spin:1.35, beam:1.35, whoosh:1.35, bell:1.35, godRising:1.35, zashu:1.35, ssrJackpot:1.4 };
let seCurrentBoost = 1;
function playSe(name, opts){
  if(!actx || audioSettings.se<=0.005) return;
  const now = actx.currentTime;
  if(seLastAt[name]!=null && now - seLastAt[name] < (SE_MIN_GAP[name]||0.05)) return;
  seLastAt[name] = now;
  const fn = SE_DEFS[name];
  if(fn){
    seCurrentBoost = SE_VOL_BOOST[name] || 1;
    fn(now, opts||{});
    seCurrentBoost = 1;
  }
}
function seTone(t, o){
  const osc = actx.createOscillator(), g = actx.createGain();
  const dur = o.dur||0.15;
  osc.type = o.type||'sine';
  osc.frequency.setValueAtTime(o.freq||440, t);
  if(o.freqEnd) osc.frequency.exponentialRampToValueAtTime(Math.max(o.freqEnd,1), t+dur);
  g.gain.setValueAtTime(0.0001, t);
  g.gain.linearRampToValueAtTime((o.vol!=null?o.vol:0.5)*seCurrentBoost, t+(o.attack||0.005));
  g.gain.exponentialRampToValueAtTime(0.001, t+dur);
  osc.connect(g); g.connect(seGain);
  osc.start(t); osc.stop(t+dur+0.05);
}
function seNoise(t, o){
  const dur = o.dur||0.2;
  const len = Math.max(1, Math.floor(actx.sampleRate*dur));
  const buf = actx.createBuffer(1, len, actx.sampleRate);
  const d = buf.getChannelData(0);
  for(let i=0;i<len;i++) d[i] = Math.random()*2-1;
  const src = actx.createBufferSource(); src.buffer = buf;
  const f = actx.createBiquadFilter();
  f.type = o.filterType||'lowpass';
  f.frequency.setValueAtTime(o.filterFreq||1000, t);
  if(o.filterEnd) f.frequency.exponentialRampToValueAtTime(Math.max(o.filterEnd,10), t+dur);
  const g = actx.createGain();
  g.gain.setValueAtTime((o.vol!=null?o.vol:0.4)*seCurrentBoost, t);
  g.gain.exponentialRampToValueAtTime(0.001, t+dur);
  src.connect(f); f.connect(g); g.connect(seGain);
  src.start(t); src.stop(t+dur+0.05);
}
// ループノイズ+音量LFO(揺らぎ)付きのノイズ再生。炎や竜巻など長い持続音に使う
function seNoiseLfo(t, o){
  const dur = o.dur||1;
  const len = Math.max(1, Math.floor(actx.sampleRate*Math.min(dur,1.5)));
  const buf = actx.createBuffer(1, len, actx.sampleRate);
  const d = buf.getChannelData(0);
  for(let i=0;i<len;i++) d[i] = Math.random()*2-1;
  const src = actx.createBufferSource(); src.buffer = buf; src.loop = true;
  const f = actx.createBiquadFilter();
  f.type = o.filterType||'lowpass';
  f.frequency.setValueAtTime(o.filterFreq||800, t);
  if(o.filterEnd) f.frequency.exponentialRampToValueAtTime(Math.max(o.filterEnd,10), t+dur);
  const g = actx.createGain();
  const v0 = (o.volStart!=null ? o.volStart : (o.vol||0.4)) * seCurrentBoost;
  const vEnd = o.volEnd!=null ? o.volEnd*seCurrentBoost : null;
  g.gain.setValueAtTime(Math.max(v0,0.001), t);
  if(vEnd!=null) g.gain.linearRampToValueAtTime(Math.max(vEnd,0.001), t+dur*0.8);
  g.gain.setValueAtTime(vEnd!=null?Math.max(vEnd,0.001):Math.max(v0,0.001), t+dur*0.85);
  g.gain.exponentialRampToValueAtTime(0.001, t+dur);
  if(o.lfoFreq){
    const lfo = actx.createOscillator(), lg = actx.createGain();
    lfo.frequency.value = o.lfoFreq;
    lg.gain.value = (o.lfoDepth||0.35) * Math.max(v0, vEnd||0);
    lfo.connect(lg); lg.connect(g.gain);
    lfo.start(t); lfo.stop(t+dur+0.05);
  }
  src.connect(f); f.connect(g); g.connect(seGain);
  src.start(t); src.stop(t+dur+0.05);
}
const SE_DEFS = {
  // 通常のボタンタップ。提供音源(choice)を鳴らし、未ロード時だけ合成の「ポン」に落とす
  tap(t){ if(!seChoice.play(t)) seTone(t, {freq:660, freqEnd:440, dur:0.09, type:'sine', vol:0.45}); },
  // モンスター選択のカード送り「シュッ」(紙のカードをめくる/弾く音)
  cardSwipe(t){
    // 高域から下がっていくノイズのひと吹き = 空気が抜ける「シュッ」
    seNoise(t, {dur:0.10, vol:0.34, filterType:'bandpass', filterFreq:5600, filterEnd:1300});
    // カードの縁が擦れる細い高域を少し重ねる
    seNoise(t+0.008, {dur:0.055, vol:0.15, filterType:'highpass', filterFreq:3600});
    // めくり終わりの「トッ」(紙が指から離れる当たり)
    seTone(t+0.03, {freq:1250, freqEnd:520, dur:0.05, type:'triangle', vol:0.10, attack:0.003});
  },
  // 試合開始・状態変化発動「ジャキーン」(大きなハサミ/刀で斬るような金属音)
  jakiin(t){
    // 立ち上がりの金属スクレイプ(刃が擦れる鋭いノイズ)
    seNoise(t, {dur:0.05, vol:0.5,  filterType:'bandpass', filterFreq:6000, filterEnd:3400});
    seNoise(t, {dur:0.09, vol:0.26, filterType:'highpass', filterFreq:4200});
    // 金属的な非整数倍音の鳴り(上昇グライドは控えめにして「キーン」と伸ばす)
    const ring=(f,d,v,dt)=>{
      seTone(t+(dt||0), {freq:f,      freqEnd:f*1.03, dur:d,      type:'square', vol:v,      attack:0.002});
      seTone(t+(dt||0), {freq:f*2.76,               dur:d*0.7,  type:'sine',   vol:v*0.5,  attack:0.002}); // 非整数倍音
      seTone(t+(dt||0), {freq:f*5.4,                dur:d*0.5,  type:'sine',   vol:v*0.3,  attack:0.002});
      seTone(t+(dt||0), {freq:f*8.9,                dur:d*0.35, type:'sine',   vol:v*0.16, attack:0.002}); // 高い金属倍音
    };
    ring(1500, 0.5,  0.22, 0);
    ring(2020, 0.45, 0.14, 0.02); // 少しずらして厚みと「キーン」感
    seNoise(t+0.02, {dur:0.4, vol:0.06, filterType:'highpass', filterFreq:7000}); // きらめく余韻
  },
  // トレーニング実行「ポワポワ」(ステータスが伸びていく上昇音)
  train(t){
    const notes = [523, 659, 784, 1047];
    notes.forEach((f,i)=>{
      seTone(t+i*0.13, {freq:f*0.97, freqEnd:f, dur:0.28, type:'sine', vol:0.4, attack:0.03});
      seTone(t+i*0.13, {freq:f*1.99, freqEnd:f*2.02, dur:0.2, type:'sine', vol:0.12, attack:0.03});
    });
  },
  // アイテム取得「ピュイン」
  pickup(t){
    seTone(t, {freq:880, freqEnd:1760, dur:0.1, type:'triangle', vol:0.45});
    seTone(t+0.08, {freq:1320, freqEnd:2200, dur:0.12, type:'sine', vol:0.3});
  },
  // 技発射「ボゥ」(単発/連射/範囲で変化)
  fire(t, opts){
    const kind = opts.kind||'single';
    if(kind==='aoe'){
      // tier3範囲技: エフェクトの持続時間(opts.dur)に合わせた長く強い轟音
      const d = Math.min(2.8, Math.max(0.7, opts.dur||0.9));
      seNoise(t, {dur:d, vol:0.42, filterFreq:1500, filterEnd:110});
      seTone(t, {freq:190, freqEnd:50, dur:d, type:'sawtooth', vol:0.26});
      seTone(t, {freq:95, freqEnd:38, dur:d*0.95, type:'sine', vol:0.42});
      seTone(t, {freq:63, dur:d*0.9, type:'sine', vol:0.2}); // 近接周波数のうなりでゴゴゴ感
      seNoise(t+d*0.55, {dur:d*0.45, vol:0.2, filterType:'highpass', filterFreq:2500}); // 余韻のシュウウ
    } else if(kind==='burst'){
      // 連射: 鋭い銃声の連発
      for(let i=0;i<3;i++){
        const tt=t+i*0.09;
        seNoise(tt, {dur:0.03, vol:0.6,  filterType:'highpass', filterFreq:2000}); // 発砲クラック
        seNoise(tt, {dur:0.1,  vol:0.32, filterType:'lowpass',  filterFreq:1300, filterEnd:150}); // 銃身の轟き
        seTone(tt,  {freq:190, freqEnd:60, dur:0.08, type:'square', vol:0.28}); // 破裂の芯
      }
    } else {
      // 単発: 「バァン」という銃声
      seNoise(t, {dur:0.04, vol:0.85, filterType:'highpass', filterFreq:1800}); // 発砲の鋭いクラック
      seNoise(t, {dur:0.18, vol:0.55, filterType:'lowpass',  filterFreq:1400, filterEnd:120}); // 銃身の轟き(ボディ)
      seTone(t,  {freq:170, freqEnd:48, dur:0.16, type:'square', vol:0.4}); // 低い破裂音の芯
      seNoise(t+0.05, {dur:0.22, vol:0.14, filterType:'highpass', filterFreq:2600}); // 硝煙/反響の余韻
    }
  },
  // 技被弾: 重く痛そうな衝撃音
  hitTaken(t){
    seTone(t, {freq:180, freqEnd:42, dur:0.32, type:'sine',     vol:0.6});  // ドスンと落ちる低音の芯
    seTone(t, {freq:110, freqEnd:34, dur:0.34, type:'triangle', vol:0.4});  // body
    seTone(t, {freq:70,              dur:0.4,  type:'sine',     vol:0.3, attack:0.002}); // 腹に来る超低音
    seNoise(t,      {dur:0.09, vol:0.4,  filterType:'lowpass',  filterFreq:1800, filterEnd:300}); // 叩きつけのスラップ(痛い)
    seNoise(t+0.01, {dur:0.05, vol:0.3,  filterType:'bandpass', filterFreq:2600}); // 骨に響くパチッ
  },
  // ガッツ不足「ピピピッ」
  noGuts(t){
    for(let i=0;i<3;i++) seTone(t+i*0.08, {freq:1250, dur:0.045, type:'square', vol:0.28});
  },
  // インフェルノ・ファイアウェーブ「ボオオオオ」(燃え盛る炎)
  fireRoar(t, o){
    const d = Math.min(3, Math.max(0.8, (o&&o.dur)||1.2));
    seNoiseLfo(t, {dur:d, vol:0.45, filterFreq:950, filterEnd:280, lfoFreq:8, lfoDepth:0.45});
    seTone(t, {freq:90, freqEnd:45, dur:d, type:'sawtooth', vol:0.24});
    for(let i=0;i<5;i++){ // パチパチと爆ぜる音
      seNoise(t + Math.random()*d*0.8, {dur:0.04, vol:0.13, filterType:'highpass', filterFreq:3200});
    }
  },
  // クリスタルレイン「パリパリパリ」(高く凍てつく、氷が砕ける音)
  iceCrack(t, o){
    const d = Math.min(2.5, Math.max(0.8, (o&&o.dur)||1.2));
    const n = Math.round(d*8)+4; // 細かく連続した「パリパリ」
    for(let i=0;i<n;i++){
      const tt = t + i*(d/n) + Math.random()*0.03;
      const f = 3200 + Math.random()*2800; // 高音域(氷の冷たさ)
      seTone(tt, {freq:f, freqEnd:f*1.15, dur:0.05, type:'triangle', vol:0.24}); // 上昇でパキッと
      seTone(tt, {freq:f*1.5, dur:0.03, type:'sine', vol:0.12});                 // 倍音のきらめき
      seNoise(tt, {dur:0.03, vol:0.16, filterType:'highpass', filterFreq:6500}); // 砕けるノイズ
    }
    seNoise(t+d*0.85, {dur:0.3, vol:0.2, filterType:'highpass', filterFreq:5500}); // 最後にシャラーン
  },
  // 竜巻アタック「ゴオオオオ」(最初から轟音+地響き)
  tornado(t, o){
    const d = Math.min(3, Math.max(1, (o&&o.dur)||2));
    seNoiseLfo(t, {dur:d, vol:0.55, filterFreq:900, filterEnd:450, lfoFreq:11, lfoDepth:0.3}); // 風の轟音
    seNoiseLfo(t, {dur:d, vol:0.5, filterFreq:130, lfoFreq:5.5, lfoDepth:0.5});               // 地響きの揺れ
    seTone(t, {freq:44, dur:d, type:'sine', vol:0.42});      // 地鳴りの超低音
    seTone(t, {freq:60, dur:d, type:'sawtooth', vol:0.2});
  },
  // シェルアタック「シュルルルル」(回転音)
  spin(t, o){
    const d = Math.min(1.6, Math.max(0.6, (o&&o.dur)||1));
    seNoiseLfo(t, {dur:d, vol:0.34, filterType:'bandpass', filterFreq:2600, lfoFreq:15, lfoDepth:0.8});
    seTone(t, {freq:640, freqEnd:900, dur:d, type:'sine', vol:0.07});
  },
  // 熱視線・サイコキネシス・モッチ砲・フラワービーム・天河天翔(持続レーザー: 低く尖った音+うなり)
  beam(t, o){
    const d = Math.min(2.6, Math.max(0.5, (o&&o.dur)||1));
    seTone(t, {freq:1400, freqEnd:650, dur:0.12, type:'sawtooth', vol:0.16}); // 撃ち出しのザップ
    seTone(t, {freq:330, dur:d, type:'sawtooth', vol:0.2, attack:0.015});
    seTone(t, {freq:333, dur:d, type:'sawtooth', vol:0.18, attack:0.015}); // わずかにずらしてうなり
    seTone(t, {freq:165, dur:d, type:'square', vol:0.13, attack:0.015});  // 低域の芯
    seNoise(t, {dur:d, vol:0.05, filterType:'bandpass', filterFreq:2400});
  },
  // レクイエムエンド「シュンシュンシュン」(鋭い風切り3連)
  whoosh(t){
    for(let i=0;i<3;i++){
      const tt=t+i*0.09;
      seNoise(tt, {dur:0.1,  vol:0.4,  filterType:'bandpass', filterFreq:6500, filterEnd:1200}); // 高く鋭い風切り
      seNoise(tt, {dur:0.06, vol:0.22, filterType:'highpass', filterFreq:5000}); // 切っ先の「シャッ」
    }
  },
  // ピクシー「ビッグバン」発射音「ビューン」(甲高い音から下がっていく黒い球体の発射音)
  voidLaunch(t, opts){
    const d = Math.max(0.15, Math.min(0.6, (opts&&opts.dur)||0.35));
    seTone(t, {freq:1400, freqEnd:220, dur:d,      type:'sawtooth', vol:0.3});  // 甲高いところから下がる芯
    seTone(t, {freq:700,  freqEnd:110, dur:d*0.9,  type:'sine',     vol:0.24}); // 低音side
    seNoise(t, {dur:d*0.6, vol:0.18, filterType:'bandpass', filterFreq:3000, filterEnd:600}); // シュー
  },
  // 天の慈悲「リンリンリーン」(残響たっぷりの鐘の音)
  bell(t){
    // 実際の鐘に近い非整数倍音(ハム・プライム・ティアス・クイント・ノミナル)を重ねて長く響かせる
    const ring=(tt,f,d,v)=>{
      seTone(tt, {freq:f*0.5,  dur:d*1.5, type:'sine', vol:v*0.5,  attack:0.008});
      seTone(tt, {freq:f,      dur:d,     type:'sine', vol:v,      attack:0.008});
      seTone(tt, {freq:f*1.19, dur:d*0.85,type:'sine', vol:v*0.5,  attack:0.008});
      seTone(tt, {freq:f*1.5,  dur:d*0.7, type:'sine', vol:v*0.35, attack:0.008});
      seTone(tt, {freq:f*2.0,  dur:d*0.55,type:'sine', vol:v*0.3,  attack:0.008});
      seTone(tt, {freq:f*2.74, dur:d*0.35,type:'sine', vol:v*0.2,  attack:0.008});
    };
    ring(t,      1568, 1.1, 0.3);
    ring(t+0.24, 1568, 1.1, 0.28);
    ring(t+0.5,  2093, 2.4, 0.34); // 最後の一打は長く響かせる
  },
  // 召喚演出・光の柱が天から落ちる「チュピーン」
  // (降ってくるきらめき → 着地して神々しい鐘＋天使の和音が広がる)
  chupiin(t){
    // 天から降りてくるきらめき(高音から降下)
    for(let i=0;i<6;i++){
      const f = 5000 - i*560;
      seTone(t+i*0.045, {freq:f, freqEnd:f*0.9, dur:0.16, type:'triangle', vol:0.12, attack:0.003});
      seTone(t+i*0.045, {freq:f*2, dur:0.08, type:'sine', vol:0.05, attack:0.003}); // 上倍音のきらめき
    }
    seNoise(t, {dur:0.32, vol:0.05, filterType:'highpass', filterFreq:8000}); // 降下のシャラ
    // 着地の「ピーン」: 明るい鐘(実際の鐘に近い非整数倍音)を長く残響させる
    const land = t + 0.3;
    const ring = (f, d, v)=>{
      seTone(land, {freq:f*0.5,  dur:d*1.4, type:'sine', vol:v*0.45, attack:0.004});
      seTone(land, {freq:f,      dur:d,     type:'sine', vol:v,      attack:0.004});
      seTone(land, {freq:f*1.5,  dur:d*0.8, type:'sine', vol:v*0.5,  attack:0.004});
      seTone(land, {freq:f*2.0,  dur:d*0.6, type:'sine', vol:v*0.32, attack:0.004});
      seTone(land, {freq:f*2.67, dur:d*0.4, type:'sine', vol:v*0.18, attack:0.004});
      seTone(land, {freq:f*3.4,  dur:d*0.28,type:'sine', vol:v*0.1,  attack:0.004});
    };
    ring(1568, 1.8, 0.24);
    ring(2093, 1.5, 0.15);
    seNoise(land, {dur:0.7, vol:0.05, filterType:'highpass', filterFreq:7500}); // 着地の光の弾け
    // 天使の和音が芽生える(ゆっくり立ち上げて神々しく)
    [523, 659, 784, 1047].forEach((f,i)=> seTone(land, {freq:f, dur:1.8, type:'sine', vol:0.06-i*0.008, attack:0.5}));
  },
  // 召喚演出・光が中心へ細く収束していく「シュワァー」
  // (フィルタが開くノイズ + 天使の合唱パッドで満ちていく神々しさ)
  shuwaa(t){
    seNoiseLfo(t,     {dur:2.4, volStart:0.02, volEnd:0.24, filterType:'bandpass', filterFreq:500,  filterEnd:6200, lfoFreq:5, lfoDepth:0.2});
    seNoiseLfo(t+0.1, {dur:2.2, volStart:0.01, volEnd:0.16, filterType:'highpass', filterFreq:1400, filterEnd:7000, lfoFreq:8, lfoDepth:0.28});
    // 合唱パッド(オクターブ＋完全五度を薄く重ね、わずかにデチューンしてうねらせる)
    const choir = (f, v)=>{
      seTone(t, {freq:f,       dur:2.6, type:'sine', vol:v,      attack:0.7});
      seTone(t, {freq:f*1.004, dur:2.6, type:'sine', vol:v*0.7,  attack:0.7}); // デチューンのうねり
      seTone(t, {freq:f*2,     dur:2.4, type:'sine', vol:v*0.4,  attack:0.8});
      seTone(t, {freq:f*3,     dur:2.2, type:'sine', vol:v*0.16, attack:0.9});
    };
    choir(392, 0.10);  // ソ
    choir(523, 0.09);  // ド
    choir(659, 0.07);  // ミ
    choir(784, 0.05);  // ソ(上)
    seNoise(t+1.8, {dur:0.8, vol:0.05, filterType:'highpass', filterFreq:6800}); // 収束のシャラーン
  },
  // 敵をキルした時: 人を斬って血の出る「ズバシュッ」
  kill(t){
    seNoise(t,      {dur:0.05, vol:0.5,  filterType:'bandpass', filterFreq:3800, filterEnd:1400}); // 刃が入る「シャッ」
    seTone(t,       {freq:900, freqEnd:120, dur:0.12, type:'sawtooth', vol:0.16}); // 斬撃のヒュッ(下降)
    seNoise(t+0.03, {dur:0.22, vol:0.42, filterType:'lowpass', filterFreq:1500, filterEnd:250}); // 肉を裂く「ブシュッ」(湿った質感)
    seTone(t+0.03,  {freq:150, freqEnd:50, dur:0.2,  type:'sine', vol:0.42}); // 血が噴く重い芯
    seNoise(t+0.09, {dur:0.16, vol:0.16, filterType:'highpass', filterFreq:2000}); // 血しぶきの余韻
  },
  // 勝利ファンファーレ(リザルト画面・約3.6秒)
  fanfare(t){
    const N=(dt,f,d,v)=>{
      seTone(t+dt, {freq:f, dur:d, type:'square', vol:(v||0.3)*0.55});
      seTone(t+dt, {freq:f/2, dur:d, type:'triangle', vol:(v||0.3)*0.45});
    };
    // 第1フレーズ: パパパ、パーン!
    N(0,    784, 0.15); N(0.17, 784, 0.15); N(0.34, 784, 0.15);
    N(0.52, 1047, 0.45, 0.34);
    // 第2フレーズ: 駆け上がり
    N(1.05, 880, 0.15); N(1.21, 988, 0.15); N(1.38, 1047, 0.4, 0.32);
    // 第3フレーズ: さらに高く駆け上がって大団円
    N(1.85, 1047, 0.14); N(2.0, 1175, 0.14); N(2.16, 1319, 0.14);
    N(2.34, 1568, 0.9, 0.38);
    [523,659,784,1047,1319].forEach(f=>seTone(t+2.34, {freq:f, dur:1.1, type:'triangle', vol:0.11, attack:0.05}));
    seNoise(t+0.52, {dur:0.3, vol:0.08, filterType:'highpass', filterFreq:5000});
    seNoise(t+2.34, {dur:0.7, vol:0.13, filterType:'highpass', filterFreq:5000}); // シャーンという輝き
  },
  // 敗北・その他(悲しげな下降フレーズ・約2.4秒)
  sad(t){
    const notes=[[0,659],[0.42,587],[0.84,523],[1.22,494]];
    for(const [dt,f] of notes){
      seTone(t+dt, {freq:f, dur:0.55, type:'triangle', vol:0.3, attack:0.04});
      seTone(t+dt, {freq:f/2, dur:0.55, type:'sine', vol:0.18, attack:0.04});
    }
    seTone(t+1.62, {freq:440, dur:1.0, type:'triangle', vol:0.28, attack:0.06});
    seTone(t+1.62, {freq:220, dur:1.0, type:'sine', vol:0.2, attack:0.06});
    seTone(t+1.62, {freq:262, dur:1.0, type:'sine', vol:0.12, attack:0.06});
  },
  // ゴッドライジング「ジャジャジャジャーン」(ベートーヴェン「運命」の重々しい動機: ソソソ→ミ♭)
  godRising(t){
    // 一撃ごとに低音を重ねて重々しく打ち込む
    const hit=(tt,f,d,v)=>{
      seTone(tt, {freq:f,      dur:d,      type:'sawtooth', vol:v,      attack:0.004}); // 主音
      seTone(tt, {freq:f*0.5,  dur:d,      type:'square',   vol:v*0.7,  attack:0.004}); // 1オクターブ下(重み)
      seTone(tt, {freq:f*0.25, dur:d*1.05, type:'sine',     vol:v*0.55, attack:0.004}); // 2オクターブ下の芯
      seTone(tt, {freq:f*1.5,  dur:d*0.7,  type:'triangle', vol:v*0.18, attack:0.004}); // 上倍音でギラつき
      seNoise(tt, {dur:0.05, vol:0.12, filterType:'highpass', filterFreq:1800});         // アタックのザッ
    };
    const G=392, Eb=311;   // ソ → ミ♭
    hit(t,       G,  0.15, 0.42);  // ジャ
    hit(t+0.17,  G,  0.15, 0.42);  // ジャ
    hit(t+0.34,  G,  0.15, 0.42);  // ジャ
    hit(t+0.56,  Eb, 1.25, 0.5);   // ジャーン(長く重く伸ばす)
    // 締めの重低音の轟き
    seTone(t+0.56, {freq:Eb*0.25, freqEnd:Eb*0.2, dur:1.35, type:'sine', vol:0.42, attack:0.006});
    seNoise(t+0.56, {dur:0.55, vol:0.14, filterFreq:1100, filterEnd:110});
  },
  // ガチャSSR獲得: 内蔵音声(パチンコ大当たり確定音)を再生。
  ssrJackpot(t, o){ playSsrJackpotOnce(); },
  // ゼウス(SSR)装備時のtier3専用: 内蔵音声を再生。未ロード/取得失敗時はゴッドライジング合成音にフォールバック。
  zeusTier3(t, o){ if(!playZeusTier3Once()) SE_DEFS.godRising(t, o); },
  // ちょこ(ピクシーSSR)専用。未ロード時は従来のSEにフォールバックする
  chocoSummon(t, o){ if(!seChocoSummon.play()) SE_DEFS.shuwaa(t, o); },
  chocoVanish(t, o){ if(!seChocoVanish.play()) SE_DEFS.voidLaunch(t, o); },
  chocoHit(t, o){ if(!seChocoHit.play()) SE_DEFS.hitTaken(t, o); },
  // 提供音源の技SE/購入SE。いずれも未ロード時は従来のSEにフォールバックする
  buy(t, o){ if(!seBuy.play(t)) SE_DEFS.pickup(t, o); },
  darkHoust(t, o){ if(!seDarkHoust.play(t)) SE_DEFS.zashu(t, o); },
  requiemEnd(t, o){ if(!seRequiemEnd.play(t)) SE_DEFS.whoosh(t, o); },
  mocchiBeam(t, o){ if(!seMocchiBeam.play(t)) SE_DEFS.beam(t, o); },
  monta(t, o){ if(!seMonta.play(t)) SE_DEFS.fire(t, o); },
  crystalRain(t, o){ if(!seCrystalRain.play(t)) SE_DEFS.iceCrack(t, o); },
  // ヒノトリ tier3「ファイアウェーブ」= 提供音源(bard)のうしろに炎の持続音をつなげる
  fireWave(t, o){
    if(seBard.play(t)) SE_DEFS.fireRoar(t + Math.max(0, seBard.dur() - 0.12), o);
    else SE_DEFS.fireRoar(t, o);
  },
  // ペルセポネ tier3「アムピトリテ」: 同じ発射音を少しずらして3回鳴らし槍の3連射を表す
  // (間隔は技の burstGap=0.12 に合わせてある)
  amphitrite(t, o){
    if(!seAmphiShot.play(t)){ SE_DEFS.whoosh(t, o); return; }
    seAmphiShot.play(t + 0.12);
    seAmphiShot.play(t + 0.24);
  },
  // 同・着弾ドームの爆発(spawnGroundBlast から blast.se 経由でドーム1個ごとに鳴る)
  amphitriteBlast(t, o){ if(!seAmphiBlast.play(t)) SE_DEFS.fireRoar(t, o); },
  // 轟金剛(ゴーレムのSSR)専用。未ロード時は従来のSEに落とす
  gokongo(t, o){ if(!seGokongo.play(t)) SE_DEFS.tornado(t, o); },
  gokongoWin(t, o){ if(!seGokongoWin.play(t)) SE_DEFS.fanfare(t, o); },
  gokongoKill(t, o){ if(!seGokongoKill.play(t)) SE_DEFS.kill(t, o); },
  // 大喰いの利世(ウンディーネのSSR)専用。未ロード時は従来のSEに落とす
  rize(t, o){ if(!seRize.play(t)) SE_DEFS.whoosh(t, o); },
  rizeKill(t, o){ if(!seRizeKill.play(t)) SE_DEFS.kill(t, o); },
  aquaKill(t, o){ if(!seAquaKill.play(t)) SE_DEFS.kill(t, o); },
  gutsTier3(t, o){ if(!seGutsTier3.play(t)) SE_DEFS.whoosh(t, o); },
  rizeHit(t, o){ if(!seRizeHit.play(t)) SE_DEFS.hitTaken(t, o); },
  // イルミネ tier1「ヴェノムエッジ」
  venomEdge(t, o){ if(!seVenomEdge.play(t)) SE_DEFS.fire(t, o); },
  // 同 tier2「アサルトアロー」: tier1と同じ音を技のburstGap(0.09)に合わせて3連射する
  assaultArrow(t, o){
    if(!seVenomEdge.play(t)){ SE_DEFS.fire(t, Object.assign({}, o, {kind:'burst'})); return; }
    seVenomEdge.play(t + 0.09);
    seVenomEdge.play(t + 0.18);
  },
  // 同 tier3「レクイエムエンド」の着弾ドーム(ドーム1個ごとに鳴る)
  requiemBlast(t, o){ if(!seRequiemBlast.play(t)) SE_DEFS.fireRoar(t, o); },
  // タイトル画面「TAP START」。未ロード時はジャキーンにフォールバック
  titleStart(t, o){ if(!seTitleStart.play()) SE_DEFS.jakiin(t, o); },
  // ダークホウスト「ズバシュ×5」(人を斬って血の出る黒い斬撃の5連)
  zashu(t){
    for(let i=0;i<5;i++){
      const tt=t+i*0.11;
      seNoise(tt,       {dur:0.045, vol:0.44, filterType:'bandpass', filterFreq:4200, filterEnd:1500}); // 刃の「シャッ」
      seTone(tt,        {freq:1100, freqEnd:200, dur:0.09, type:'sawtooth', vol:0.12}); // 斬撃の下降
      seNoise(tt+0.025, {dur:0.16, vol:0.32, filterType:'lowpass', filterFreq:1400, filterEnd:240}); // 肉を裂く「ブシュッ」
      seTone(tt+0.025,  {freq:170, freqEnd:60, dur:0.14, type:'sine', vol:0.3}); // 血の重い芯
    }
  },
};
/* ===== SSRスキン専用SE(data.js の SKIN_MEDIA から自動登録) =====
   SE名は 'skinSe:<スキンid>:<区分>'。SE_DEFS へ入れるので、管理者画面のSE確認にも
   自動で並ぶ。音源が未ロード・取得失敗のときは既存のSEへ落ちるので無音にはならない。 */
const SKIN_SE_FALLBACK = { tier3:'fire', hit:'hitTaken', kill:'kill', win:'fanfare' };
const SKIN_SE_GAP      = { tier3:0.6,    hit:0.3,        kill:0.4,    win:1.5 };
const skinMediaSeOneShots = {};   // SE名 -> ワンショット
function skinMediaSeName(skinId, slot){
  const name = `skinSe:${skinId}:${slot}`;
  return skinMediaSeOneShots[name] ? name : null;
}
function ensureSkinMediaSeBuffers(skinId){
  Object.keys(SKIN_SE_FALLBACK).forEach(slot=>{
    const one = skinMediaSeOneShots[`skinSe:${skinId}:${slot}`];
    if(one) one.ensure();
  });
}
Object.keys(typeof SKIN_MEDIA!=='undefined' ? SKIN_MEDIA : {}).forEach(id=>{
  const se = SKIN_MEDIA[id].se;
  if(!se) return;
  Object.keys(se).forEach(slot=>{
    if(!se[slot] || !SKIN_SE_FALLBACK[slot]) return;
    const name = `skinSe:${id}:${slot}`;
    const one = createSeOneShot('./' + se[slot], 1.2);
    skinMediaSeOneShots[name] = one;
    SE_MIN_GAP[name] = SKIN_SE_GAP[slot];
    SE_DEFS[name] = (t, o)=>{ if(!one.play(t)) SE_DEFS[SKIN_SE_FALLBACK[slot]](t, o); };
  });
});
// メニュー系の<button>タップで共通の「ポン」を鳴らす
document.addEventListener('click', (e)=>{
  if(!e.target || !e.target.closest) return;
  // 管理者の音声確認タブでは、確認したいSE/BGMに共通タップ音が被らないよう「ポン」を鳴らさない
  if(e.target.closest('#adminSePane')) return;
  // モンスター選択/マスモン選択の送りボタン(下段の‹›と、カード上の≪≫)は専用の
  // カード送りSEを鳴らすので、共通タップ音は重ねない
  if(e.target.closest('.ml-nav') || e.target.closest('.ml-card-nav')) return;
  if(e.target.closest('button')) playSe('tap');
}, true);

// ===== BGM(ステップシーケンサ) =====
// 16分音符単位で先読みスケジュールする。トラックは 'title' / 'battle' / 'shop'。
// battleは残り人数に応じて intensity 0(序盤)→1(中盤)→2(終盤)→3(残り5人以下=決戦)
// →4(残り2人=ラストバトル) が上がる
const bgmState = { desired:'title', current:null, step:0, nextTime:0, intensity:0, timerId:null };
const MIDI = n => 440*Math.pow(2,(n-69)/12);
function bgmSetTrack(name){
  if(bgmState.desired===name) return;
  bgmState.desired = name;
  // 試合以外の画面へ移るときはintensityを持ち越さない(前の試合の決戦BGMが後を引かないように)。
  // nullは試合中の演出でも使うのでここでは触らない。
  if(name==='title' || name==='shop' || name==='training') bgmState.intensity = 0;
  // 専用BGMを持つSSRスキンを装備中なら、試合開始と同時にその3曲の読み込みを始めておく
  // (残り人数がその区間に入ってから取りに行くと間に合わないため)。専用SEも同じ理由で先読みする
  if(name==='battle' && typeof player!=='undefined' && player && typeof entitySkinId==='function'){
    const skinId = entitySkinId(player);
    ensureSkinBgmBuffers(skinId);
    ensureSkinMediaSeBuffers(skinId);
  }
  if(actx && bgmTrackGain){
    // 切替時は短くフェードアウト→インして繋ぎ目を柔らかく
    const t = actx.currentTime;
    bgmTrackGain.gain.cancelScheduledValues(t);
    bgmTrackGain.gain.setValueAtTime(bgmTrackGain.gain.value, t);
    bgmTrackGain.gain.linearRampToValueAtTime(0.0001, t+0.25);
    bgmTrackGain.gain.linearRampToValueAtTime(1, t+0.9);
  }
}
function bgmUpdateBattleIntensity(aliveCount){
  /* レイドは総力戦なので、最初から最後まで「残り2人」の盛り上がり(ラストバトル)で固定する。
     人数で決めると、ボス+4人=5体からbotが減るたびに曲が切り替わって落ち着かない。
     専用BGMを持つSSRスキンを装備していれば、そのラストバトル曲が優先される
     (選び分けは bgmFileLoopTarget の activeSkinBgmSet 側で既に効いている)。 */
  if(typeof game!=='undefined' && game && game.raid){ bgmState.intensity = 4; return; }
  bgmState.intensity = aliveCount<=2 ? 4 : aliveCount<=5 ? 3 : aliveCount<=10 ? 2 : aliveCount<=20 ? 1 : 0;
}
// テスト用: intensityを直接指定する(管理者画面のBGM確認から使う)
function bgmSetIntensity(n){ bgmState.intensity = n|0; }

// 一部のBGMは合成ではなく提供動画の音声(mp3)をループ再生する。
// 残り5人以下(intensity 3)=決戦 / 残り2人(intensity 4)=ラストバトル / ショップ画面。
// 音源が未ロード/取得失敗時は従来の合成BGMにフォールバックするので無音にはならない。
// monsters/*.png と同様に、実行時に読み込む外部アセットとして扱う。
// 曲ごとの音量の微調整。3曲の短時間ラウドネスを実測し、決戦BGM(bgm_final5)に合わせた値。
// 実測値(短時間LUFSの中央値): final5 -16.57 / lastbattle -16.81 / shop -16.22
// → 差は0.35LU以内(ほぼ可聴外)だが、決戦BGM基準にきっちり揃えてある。
// 体感でまだ差があれば、この数値だけを増減すれば調整できる(1.0=そのまま)。
const BGM_FILE_GAIN = { final5: 1.00, lastBattle: 1.03, shop: 0.96, lobby: 1.00, training: 1.00 };
// 曲の切替は「等パワークロスフェード」で行う。単純な線形フェードで前の曲と重ねると
// 2曲の合計音量が一時的に1.5倍近くまで上がり、切替の瞬間だけ音が大きくなる
// (決戦→ラストバトルの切替で実際に起きていた)。sin/cosカーブなら合計パワーが一定になる。
const BGM_CROSSFADE = 0.5; // 秒
// rising=true : from→to を sin カーブで上げる
// rising=false: from→to を cos カーブで下げる(上げ側と2乗の和が一定=等パワーになる)
function _equalPowerCurve(from, to, rising){
  const n = 32, arr = new Float32Array(n);
  for(let i=0;i<n;i++){
    const x = i/(n-1);
    // 下げ側は cos が 1→0 なので、始点fromから終点toへ正しく向かうよう to 基準で組む
    const v = rising ? (from + (to-from)*Math.sin(x*Math.PI/2))
                     : (to   + (from-to)*Math.cos(x*Math.PI/2));
    arr[i] = Math.max(0.0001, v);
  }
  return arr;
}
// keepPos=true の曲は「止めた時点の再生位置」を覚えていて、次に鳴らすときそこから続ける
// (ロビーBGM用。他の曲へ切り替えて戻ってきても頭から鳴り直さない)
function createBgmLoop(url, gainVal, keepPos){
  const L = { url, buffer:null, source:null, gain:null, decoding:false, vol:(gainVal!=null?gainVal:1),
              keepPos:!!keepPos, offset:0, startedAt:0 };
  L.ensure = ()=>{
    if(L.buffer || L.decoding || !actx) return;
    L.decoding = true;
    fetch(L.url).then(r=>r.arrayBuffer()).then(a=>actx.decodeAudioData(a)).then(buf=>{
      L.buffer = buf; L.decoding = false;
    }).catch(()=>{ L.decoding = false; });
  };
  L.start = ()=>{
    if(!actx || !L.buffer || L.source) return;
    const src = actx.createBufferSource(); src.buffer = L.buffer; src.loop = true;
    const g = actx.createGain();
    const t = actx.currentTime;
    g.gain.setValueAtTime(0.0001, t);
    // 等パワーで立ち上げる(古い環境でsetValueCurveAtTimeが使えなければ線形にフォールバック)
    try{ g.gain.setValueCurveAtTime(_equalPowerCurve(0, L.vol, true), t, BGM_CROSSFADE); }
    catch(e){ g.gain.linearRampToValueAtTime(L.vol, t+BGM_CROSSFADE); }
    src.connect(g); g.connect(bgmTrackGain); // bgmTrackGain経由でBGM音量・切替フェードが乗る
    const off = L.keepPos ? (L.offset % L.buffer.duration) : 0;
    src.start(t, off);
    L.startedAt = t;
    L.source = src; L.gain = g;
  };
  L.stop = ()=>{
    if(!L.source) return;
    const src = L.source, g = L.gain, t = actx.currentTime;
    try{
      g.gain.cancelScheduledValues(t);
      const cur = g.gain.value;
      g.gain.setValueAtTime(cur, t);
      // 立ち上げと相補のカーブで落とす(合計パワーが一定に保たれる)
      try{ g.gain.setValueCurveAtTime(_equalPowerCurve(cur, 0, false), t, BGM_CROSSFADE); }
      catch(e){ g.gain.linearRampToValueAtTime(0.0001, t+BGM_CROSSFADE); }
    }catch(e){}
    try{ src.stop(t+BGM_CROSSFADE+0.05); }catch(e){}
    // 止めた位置を覚えておく(フェードアウト分のズレは体感できないので停止指示の時点で記録する)
    if(L.keepPos && L.buffer) L.offset = (L.offset + Math.max(0, t - L.startedAt)) % L.buffer.duration;
    L.source = null; L.gain = null;
  };
  L.setPlaying = (on)=>{ if(on && !L.source) L.start(); else if(!on && L.source) L.stop(); };
  return L;
}
const bgmFinal5     = createBgmLoop('./audio/bgm_final5.mp3',     BGM_FILE_GAIN.final5);     // 残り5人以下(決戦)
const bgmLastBattle = createBgmLoop('./audio/bgm_lastbattle.mp3', BGM_FILE_GAIN.lastBattle); // 残り2人(ラストバトル)
const bgmShop       = createBgmLoop('./audio/bgm_shop.mp3',       BGM_FILE_GAIN.shop);       // ショップ画面
const bgmLobby      = createBgmLoop('./audio/bgm_lobby.mp3',     BGM_FILE_GAIN.lobby, true);// ロビー(既定)。位置を記憶する
const bgmTraining   = createBgmLoop('./audio/bgm_training.mp3',  BGM_FILE_GAIN.training);   // マスモンのトレーニング画面
/* SSRスキン装備時だけ使う試合中BGM3曲(残り6人以上 / 5人以下 / 2人)。
   通常のfinal5/lastbattleと同じ枠組みで曲だけ差し替える。どのスキンにどの曲を使うかは
   data.js の SKIN_MEDIA だけが持つので、スキンを足してもこの下の行は増えない。
   スキンを装備していないプレイヤーの起動時ロードを増やさないよう、試合開始時にだけ読み込む。 */
const skinBgmLoops = {};      // skinId -> { battle, final5, lastBattle }(登録されている区分だけ)
Object.keys(typeof SKIN_MEDIA!=='undefined' ? SKIN_MEDIA : {}).forEach(id=>{
  const b = SKIN_MEDIA[id].bgm;
  if(!b) return;
  const set = {};
  Object.keys(b).forEach(slot=>{ if(b[slot]) set[slot] = createBgmLoop('./' + b[slot], 1.00); });
  if(Object.keys(set).length) skinBgmLoops[id] = set;
});
// 管理者画面のBGM確認や昇格演出のbgmOnRevealで使うトラック名。'skinBgm:<スキンid>:<区分>'
function skinBgmTrack(skinId, slot){ return `skinBgm:${skinId}:${slot}`; }
function skinBgmLoopOfTrack(name){
  if(typeof name!=='string' || name.indexOf('skinBgm:')!==0) return null;
  const [, id, slot] = name.split(':');
  return (skinBgmLoops[id] && skinBgmLoops[id][slot]) || null;
}
function ensureSkinBgmBuffers(skinId){
  const set = skinBgmLoops[skinId];
  if(set) Object.keys(set).forEach(slot=> set[slot].ensure());
}
// 試合中に必要な2曲は先読みする(その場でのfetch+decode待ちで無音になるのを防ぐ)。
// ショップ/トレーニング曲は画面を開いたときに読み込む。ロビー曲は起動直後に必要なのでaudioInitで読む。
function ensureBgmFileBuffers(){ bgmFinal5.ensure(); bgmLastBattle.ensure(); }
function ensureBgmShopBuffer(){ bgmShop.ensure(); }
function ensureBgmLobbyBuffer(){ bgmLobby.ensure(); }
function ensureBgmTrainingBuffer(){ bgmTraining.ensure(); }

// ロビーBGMは提供音源(いちか)と従来の合成BGM(オリジナル)を切り替えられる。選択は端末に保存する
const LOBBY_BGM_KEY = 'aramon_lobby_bgm_v1';
const LOBBY_BGM_LABELS = { ichika:'いちか', original:'オリジナル' };
let lobbyBgmMode = 'ichika';
try{ const v = localStorage.getItem(LOBBY_BGM_KEY); if(LOBBY_BGM_LABELS[v]) lobbyBgmMode = v; }catch(e){}
function getLobbyBgmMode(){ return lobbyBgmMode; }
function setLobbyBgmMode(mode){
  if(!LOBBY_BGM_LABELS[mode]) return;
  lobbyBgmMode = mode;
  try{ localStorage.setItem(LOBBY_BGM_KEY, mode); }catch(e){}
  if(actx) updateBgmFileLoops();   // ロビーを開いたまま押しても即切り替わる
}
function toggleLobbyBgmMode(){ setLobbyBgmMode(lobbyBgmMode==='ichika' ? 'original' : 'ichika'); }
// 実音源ループの一覧。重複再生の防御はこの配列を使った「1曲だけ」の保証で行う
const BGM_FILE_LOOPS = [bgmFinal5, bgmLastBattle, bgmShop, bgmLobby, bgmTraining];
Object.keys(skinBgmLoops).forEach(id=>{
  const set = skinBgmLoops[id];
  Object.keys(set).forEach(slot=> BGM_FILE_LOOPS.push(set[slot]));
});
/* 実際の試合中(game.started)に、自分のモンスターへ専用BGMを持つSSRスキンを装備しているか。
   管理者画面のBGM確認は試合を開始しないので、game.started で確認専用の final5/last2 ボタンと
   混線しない(装備スキンに関係なく通常曲を聴ける)。 */
function activeSkinBgmSet(){
  if(!(typeof game!=='undefined' && game.started)) return null;
  if(!(typeof player!=='undefined' && player && typeof entitySkinId==='function')) return null;
  return skinBgmLoops[entitySkinId(player)] || null;
}
// いま鳴らすべき実音源ループを1つだけ返す(なければnull=合成BGMの担当)。
// 【重要】トラック名は必ず明示で判定する。以前は「title/shop以外はすべて試合中」としていたため、
// トレーニング画面で前の試合のintensity(3〜4)が残っていると決戦BGMが同時に鳴っていた。
function bgmFileLoopTarget(){
  if(!(actx && actx.state==='running' && audioSettings.bgm>0.005)) return null;
  const cur = bgmState.current;
  if(cur==='shop') return bgmShop;
  if(cur==='training') return bgmTraining;
  if(cur==='title') return lobbyBgmMode==='ichika' ? bgmLobby : null;
  // 管理者画面の音声確認・昇格演出から直接指定されたときだけ通る名前(実際の試合では使わない)
  const direct = skinBgmLoopOfTrack(cur);
  if(direct) return direct;
  if(cur==='battle'){
    // 専用BGMを持つスキンを装備しているなら、残り2人 / 残り5人以下(3〜4人含む) /
    // 残り6人以上 の3区分でそのスキンの曲を選ぶ。読み込みが間に合っていなければ
    // ここを素通りして下の通常曲にフォールバックする
    const set = activeSkinBgmSet();
    if(set){
      if(bgmState.intensity>=4 && set.lastBattle && set.lastBattle.buffer) return set.lastBattle;
      if(bgmState.intensity>=3 && set.final5 && set.final5.buffer) return set.final5;
      if(bgmState.intensity<3 && set.battle && set.battle.buffer) return set.battle;
    }
    // ラストバトル音源が使えるならそちら、無ければ決戦BGMのまま(合成に落ちるより自然)
    if(bgmState.intensity>=4 && bgmLastBattle.buffer) return bgmLastBattle;
    if(bgmState.intensity>=3) return bgmFinal5;
    return null;  // 序盤〜終盤は合成BGM
  }
  return null;    // null(停止)や未知のトラック
}
// スケジューラから毎tick呼ぶ。「目的の1曲以外は必ず止める」ので、
// 判定条件を足しても複数の実音源が同時に鳴ることはない。
function updateBgmFileLoops(){
  const want = bgmFileLoopTarget();
  BGM_FILE_LOOPS.forEach(L=>{ if(L!==want && L.source) L.stop(); });
  if(want && !want.source) want.start();
}
// 実音源のループが鳴っている間は合成パートを鳴らさない(二重再生の防止)
function bgmFileLoopActive(){ return BGM_FILE_LOOPS.some(L=>!!L.source); }
// いま望まれているトラック名(リザルト後の復帰処理が、先に決まった行き先を上書きしないよう参照する)
function bgmDesiredTrack(){ return bgmState.desired; }
function startBgmScheduler(){
  if(bgmState.timerId) return;
  bgmState.nextTime = actx.currentTime + 0.1;
  bgmState.timerId = setInterval(bgmScheduler, 90);
}
function bgmStepDur(){
  if(bgmState.current==='title' || bgmState.current==='shop' || bgmState.current==='training') return 60/92/4;
  const bpm = [116,126,138,126,132][bgmState.intensity] || 126;
  return 60/bpm/4;
}
function bgmScheduler(){
  if(!actx || actx.state!=='running') return;
  if(bgmState.current !== bgmState.desired){
    bgmState.current = bgmState.desired;
    bgmState.step = 0;
    bgmState.nextTime = Math.max(bgmState.nextTime, actx.currentTime + 0.08);
  }
  updateBgmFileLoops(); // 動画音源ループ(決戦/ラストバトル/ショップ)の開始・停止を状態に追従させる
  if(!bgmState.current || audioSettings.bgm<=0.005){
    bgmState.nextTime = actx.currentTime + 0.1; // 復帰時にまとめ鳴りしないよう追従だけさせる
    return;
  }
  while(bgmState.nextTime < actx.currentTime + 0.28){
    // 実音源が鳴っている区間は合成パートを止める。未ロード時だけ合成にフォールバックする
    if(bgmFileLoopActive()){ /* 実音源ループが担当中 */ }
    else if(bgmState.current==='title') bgmTitleStep(bgmState.step, bgmState.nextTime);
    else if(bgmState.current==='shop') bgmTitleStep(bgmState.step, bgmState.nextTime); // ショップ音源未ロード時はタイトル曲で代替
    else if(bgmState.current==='training') bgmTitleStep(bgmState.step, bgmState.nextTime); // トレーニング音源未ロード時も同様
    // スキン専用BGMを直接指定したとき(管理者確認)の未ロード時の代替。残り6人以上は通常の
    // 試合曲、決戦・ラストバトルは決戦曲で鳴らす
    else if(typeof bgmState.current==='string' && bgmState.current.indexOf('skinBgm:')===0){
      if(bgmState.current.endsWith(':battle')) bgmBattleStep(bgmState.step, bgmState.nextTime, 0);
      else bgmEpicStep(bgmState.step, bgmState.nextTime);
    }
    else if(bgmState.intensity>=3) bgmEpicStep(bgmState.step, bgmState.nextTime);      // 決戦/ラストバトル音源が未ロードのとき
    else bgmBattleStep(bgmState.step, bgmState.nextTime, bgmState.intensity);
    bgmState.step++;
    bgmState.nextTime += bgmStepDur();
  }
}
// BGM用の発音ヘルパー
function bNote(t, midi, dur, type, vol, detune){
  const osc = actx.createOscillator(), g = actx.createGain();
  osc.type = type||'triangle';
  osc.frequency.setValueAtTime(MIDI(midi), t);
  if(detune) osc.detune.setValueAtTime(detune, t);
  g.gain.setValueAtTime(0.0001, t);
  g.gain.linearRampToValueAtTime(vol!=null?vol:0.15, t+0.015);
  g.gain.setValueAtTime(vol!=null?vol:0.15, t+dur*0.6);
  g.gain.exponentialRampToValueAtTime(0.001, t+dur);
  osc.connect(g); g.connect(bgmTrackGain);
  osc.start(t); osc.stop(t+dur+0.05);
}
function bKick(t, vol){
  const osc = actx.createOscillator(), g = actx.createGain();
  osc.type='sine';
  osc.frequency.setValueAtTime(130, t);
  osc.frequency.exponentialRampToValueAtTime(45, t+0.11);
  g.gain.setValueAtTime(vol!=null?vol:0.5, t);
  g.gain.exponentialRampToValueAtTime(0.001, t+0.13);
  osc.connect(g); g.connect(bgmTrackGain);
  osc.start(t); osc.stop(t+0.16);
}
function bHat(t, vol){
  const len = Math.floor(actx.sampleRate*0.035);
  const buf = actx.createBuffer(1,len,actx.sampleRate);
  const d = buf.getChannelData(0);
  for(let i=0;i<len;i++) d[i]=Math.random()*2-1;
  const src=actx.createBufferSource(); src.buffer=buf;
  const f=actx.createBiquadFilter(); f.type='highpass'; f.frequency.value=6500;
  const g=actx.createGain();
  g.gain.setValueAtTime(vol!=null?vol:0.12, t);
  g.gain.exponentialRampToValueAtTime(0.001, t+0.035);
  src.connect(f); f.connect(g); g.connect(bgmTrackGain);
  src.start(t); src.stop(t+0.05);
}
function bCrash(t, vol){
  const len = Math.floor(actx.sampleRate*0.9);
  const buf = actx.createBuffer(1,len,actx.sampleRate);
  const d = buf.getChannelData(0);
  for(let i=0;i<len;i++) d[i]=Math.random()*2-1;
  const src=actx.createBufferSource(); src.buffer=buf;
  const f=actx.createBiquadFilter(); f.type='highpass'; f.frequency.value=4200;
  const g=actx.createGain();
  g.gain.setValueAtTime(vol!=null?vol:0.16, t);
  g.gain.exponentialRampToValueAtTime(0.001, t+0.9);
  src.connect(f); f.connect(g); g.connect(bgmTrackGain);
  src.start(t); src.stop(t+1.0);
}
function bTom(t, vol){
  const osc = actx.createOscillator(), g = actx.createGain();
  osc.type='sine';
  osc.frequency.setValueAtTime(190, t);
  osc.frequency.exponentialRampToValueAtTime(80, t+0.16);
  g.gain.setValueAtTime(vol!=null?vol:0.3, t);
  g.gain.exponentialRampToValueAtTime(0.001, t+0.18);
  osc.connect(g); g.connect(bgmTrackGain);
  osc.start(t); osc.stop(t+0.22);
}
function bSnare(t, vol){
  const len = Math.floor(actx.sampleRate*0.12);
  const buf = actx.createBuffer(1,len,actx.sampleRate);
  const d = buf.getChannelData(0);
  for(let i=0;i<len;i++) d[i]=Math.random()*2-1;
  const src=actx.createBufferSource(); src.buffer=buf;
  const f=actx.createBiquadFilter(); f.type='bandpass'; f.frequency.value=1900; f.Q.value=0.7;
  const g=actx.createGain();
  g.gain.setValueAtTime(vol!=null?vol:0.28, t);
  g.gain.exponentialRampToValueAtTime(0.001, t+0.12);
  src.connect(f); f.connect(g); g.connect(bgmTrackGain);
  src.start(t); src.stop(t+0.15);
}

// --- タイトルBGM: のどかな牧場(ハ長調・ゆったり8小節ループ) ---
// コード進行: C - F - C - G - C - Am - F - G(1小節=16ステップ)
const TITLE_CHORDS = [
  [60,64,67],[65,69,72],[60,64,67],[67,71,74],
  [60,64,67],[57,60,64],[65,69,72],[67,71,74],
];
// メロディ: [開始ステップ(128中), MIDIノート, 長さ(ステップ)] 素朴なペンタトニック調
const TITLE_MELODY = [
  [0,76,4],[4,79,4],[8,81,6],[14,79,2],
  [16,81,4],[20,79,4],[24,76,8],
  [32,72,4],[36,76,4],[40,79,6],[46,76,2],
  [48,74,8],[56,71,8],
  [64,76,4],[68,79,4],[72,81,6],[78,84,2],
  [80,84,4],[84,81,4],[88,79,8],
  [96,77,4],[100,76,4],[104,74,4],[108,72,4],
  [112,74,6],[118,71,2],[120,72,8],
];
function bgmTitleStep(step, t){
  const s = step % 128;
  const bar = Math.floor(s/16), sb = s%16;
  const chord = TITLE_CHORDS[bar];
  const dur = bgmStepDur();
  // ベース: 1・3拍目にルート音(のんびり)
  if(sb===0 || sb===8) bNote(t, chord[0]-24, dur*7, 'sine', 0.22);
  // 分散和音: 8分でやわらかく
  if(sb%2===0){
    const arpNote = chord[(sb/2)%3] ;
    bNote(t, arpNote, dur*1.8, 'triangle', 0.075);
  }
  // メロディ
  for(const [ms, note, len] of TITLE_MELODY){
    if(ms===s) bNote(t, note, dur*len*0.92, 'triangle', 0.16);
  }
  // 小鳥のさえずり風(たまに高音がピロッ)
  if(s===30 || s===94){ bNote(t, 96, dur, 'sine', 0.05); bNote(t+dur, 98, dur, 'sine', 0.04); }
}

// --- 試合中BGM: 緊張感のあるマイナー進行(残り人数で厚み・速さが増す) ---
// コード進行: Am - Am - F - G(1小節=16ステップ、4小節ループ)
const BATTLE_CHORDS = [ [57,60,64],[57,60,64],[53,57,60],[55,59,62] ];
function bgmBattleStep(step, t, lv){
  const s = step % 64;
  const bar = Math.floor(s/16), sb = s%16;
  const chord = BATTLE_CHORDS[bar];
  const root = chord[0]-24;
  const dur = bgmStepDur();
  // ベース: 8分刻みのパルス
  if(sb%2===0) bNote(t, root, dur*1.6, 'sawtooth', lv>=1?0.13:0.1);
  // ハイハット: 序盤は8分、終盤は16分
  if(lv>=2 || sb%2===0) bHat(t, sb%4===2?0.13:0.08);
  // キック: 中盤から4つ打ち
  if(lv>=1 && sb%4===0) bKick(t, 0.42);
  if(lv===0 && sb===0) bKick(t, 0.3);
  // スネア: 終盤から2・4拍
  if(lv>=2 && (sb===4 || sb===12)) bSnare(t);
  // アルペジオ: 序盤4分→中盤8分→終盤16分で刻みが細かくなる
  const arpEvery = lv>=2 ? 1 : lv>=1 ? 2 : 4;
  if(sb%arpEvery===0){
    const arpNote = chord[Math.floor(sb/arpEvery)%3]+12;
    bNote(t, arpNote, dur*1.4, 'square', 0.05);
  }
  // 終盤: 小節頭に不穏なスタブ
  if(lv>=2 && sb===0) bNote(t, chord[0], dur*6, 'sawtooth', 0.08, 8);
}

// --- 残り5人以下: 重厚で禍々しい決戦BGM(8小節=128ステップループ) ---
// コード進行: Am - F - Dm - E / Am - B♭ - F - E(B♭の半音上行とEの導音で禍々しさを出す)
const EPIC_CHORDS = [
  [57,60,64],[53,57,60],[50,53,57],[52,56,59],
  [57,60,64],[58,62,65],[53,57,60],[52,56,59],
];
// 旋律: 上昇音形の反復(ゼクエンツ)で、8小節かけて段階的に高まっていく
const EPIC_MELODY = [
  [0,57,4],[4,60,4],[8,64,4],[12,62,4],          // 低域: A-C-E-D
  [16,60,4],[20,64,4],[24,65,4],[28,64,4],        // 一段上がって C-E-F-E
  [32,62,4],[36,65,4],[40,69,4],[44,67,4],        // さらに上がって D-F-A-G
  [48,64,4],[52,68,4],[56,71,4],[60,68,4],        // E-G#-B-G#(導音で緊張)
  [64,69,4],[68,72,4],[72,76,4],[76,74,4],        // 1オクターブ上で最初の音形を反復
  [80,74,4],[84,77,4],[88,81,4],[92,79,4],        // D-F-A-G(高域)
  [96,81,3],[99,84,3],[102,81,3],[105,84,3],[108,86,4], // A-C-A-C-D 畳みかけ
  [112,88,8],[120,87,4],[124,88,4],               // E6の頂点 → 導音を挟んでループ頭のAへ
];
function bgmEpicStep(step, t){
  const s = step % 128;
  const bar = Math.floor(s/16), sb = s%16;
  const chord = EPIC_CHORDS[bar];
  const dur = bgmStepDur();
  const build = bar/7; // 0→1: 8小節かけて徐々に盛り上がる係数
  // 小節頭: クラッシュ+重厚パッド+聖歌隊風+地鳴りサブベース+うなり(禍々しさ)
  if(sb===0){
    bCrash(t, bar===0 ? 0.22 : 0.1+build*0.08);
    for(const n of chord){
      bNote(t, n, dur*15, 'sawtooth', 0.04+build*0.02, -12);
      bNote(t, n, dur*15, 'sawtooth', 0.04+build*0.02, 12);
      bNote(t, n+12, dur*15, 'triangle', 0.03+build*0.05); // 聖歌隊風(後半ほど強く)
    }
    bNote(t, chord[0]-12, dur*15, 'sawtooth', 0.1);
    bNote(t, chord[0]-24, dur*15, 'sine', 0.24);     // 地鳴りのサブベース
    bNote(t, chord[0]-24, dur*15, 'sine', 0.06, 22); // わずかにずらした同音のうなりで不穏さを出す
  }
  // 重々しいベース: ノコギリ+1オクターブ下の矩形の2枚重ね。小節末に半音下をぶつける
  if(sb%2===0){
    const bn = chord[0]-24 + (sb===14 ? -1 : 0);
    bNote(t, bn, dur*1.8, 'sawtooth', 0.2);
    bNote(t, bn-12, dur*1.8, 'square', 0.07);
  }
  // ドラム: 4つ打ち+小節終わりのダブルキック+2・4スネア+低音タム+16分ハット
  if(sb%4===0) bKick(t, 0.6);
  if(sb===14){ bKick(t, 0.5); bKick(t+dur/2, 0.5); }
  if(sb===4 || sb===12) bSnare(t, 0.3+build*0.1);
  if(sb===7 || sb===15) bTom(t, 0.32);
  bHat(t, sb%4===0?0.13:0.08);
  // 鐘のような不穏なトライトーンアクセント
  if(sb===8 && bar%2===1) bNote(t, chord[0]+18, dur*4, 'triangle', 0.05);
  // 旋律: 小節が進むほど層が厚く・強くなる(徐々に盛り上がる)
  for(const [ms, note, len] of EPIC_MELODY){
    if(ms===s){
      bNote(t, note, dur*len*0.95, 'square', 0.07+build*0.05);
      if(bar>=2) bNote(t, note+12, dur*len*0.95, 'triangle', 0.05+build*0.09);
      if(bar>=4) bNote(t, note-12, dur*len*0.95, 'sawtooth', 0.05);
      if(bar>=6) bNote(t, note+7, dur*len*0.95, 'triangle', 0.06);
    }
  }
}
